import io,json,subprocess,uuid
from pypdf import PdfWriter
import verification_v2_server as fixture
from app.models.user import User,UserRole
from app.services.auth import create_access_token
from PIL import Image
with fixture.database.SessionLocal() as db:
 u=db.query(User).filter_by(role=UserRole.LIBRARIAN).first();token=create_access_token(u.id,'librarian')
 student=db.query(User).filter_by(role=UserRole.STUDENT).first();student_token=create_access_token(student.id,'student')
pdf=PdfWriter();pdf.add_blank_page(width=300,height=400);buf=io.BytesIO();pdf.write(buf)
cover=io.BytesIO();Image.new('RGB',(20,30),'blue').save(cover,format='PNG')
title='V2 lifecycle '+uuid.uuid4().hex[:8]
program="""await page.goto('http://127.0.0.1:5174/librarian/login');await page.evaluate(t=>localStorage.setItem('bookbridge_token',t),TOKEN);await page.goto('http://127.0.0.1:5174/admin/resources');await page.getByLabel('Title',{exact:true}).fill(TITLE);await page.getByLabel('Author',{exact:true}).fill('Acceptance fixture');await page.getByLabel('License',{exact:true}).fill('Original verification content');await page.getByLabel('Distribution basis',{exact:true}).selectOption('permission');await page.getByLabel('Rights evidence',{exact:true}).fill('Original acceptance fixture authorized for local testing.');await page.locator('input[accept="image/png,image/jpeg,image/webp"]').setInputFiles({name:'cover.png',mimeType:'image/png',buffer:new Uint8Array(COVER)});await page.getByText('Cover uploaded. Save the resource to apply it.',{exact:true}).waitFor();await page.locator('input[accept=".pdf,application/pdf"]').setInputFiles({name:'fixture.pdf',mimeType:'application/pdf',buffer:new Uint8Array(BYTES)});await page.getByRole('button',{name:'Save resource',exact:true}).click();const card=page.locator('article').filter({hasText:TITLE});await card.getByText('Draft',{exact:true}).waitFor();await page.reload();await card.getByText('Draft',{exact:true}).waitFor();await page.evaluate(()=>window.confirm=()=>true);await card.getByRole('button',{name:'Review and publish',exact:true}).click();await card.getByText('Published',{exact:true}).waitFor();const access=await page.evaluate(async args=>{const list=await fetch('http://127.0.0.1:8001/digital-resources/').then(r=>r.json());const row=list.find(r=>r.title===args.title);if(!row)return false;const response=await fetch('http://127.0.0.1:8001'+row.file_url,{headers:{Authorization:'Bearer '+args.token}});return response.status===200 && !!row.reviewed_by;},{title:TITLE,token:STUDENT_TOKEN});if(!access)throw new Error('Curated student access failed');await card.getByRole('button',{name:'Unpublish',exact:true}).click();await card.getByText('Draft',{exact:true}).waitFor();await card.getByRole('button',{name:'Archive',exact:true}).click();await card.getByText('Archived',{exact:true}).waitFor();await card.getByRole('button',{name:'Restore to draft',exact:true}).click();await card.getByText('Draft',{exact:true}).waitFor();await page.evaluate(()=>localStorage.removeItem('bookbridge_token'));await page.goto('http://127.0.0.1:5174/librarian/login');return {draftReloadPublishUnpublishArchiveRestore:true};""".replace('STUDENT_TOKEN',json.dumps(student_token)).replace('TOKEN',json.dumps(token)).replace('TITLE',json.dumps(title)).replace('BYTES',json.dumps(list(buf.getvalue()))).replace('COVER',json.dumps(list(cover.getvalue()))).replace('STUDENT_TOKEN',json.dumps(student_token))
r=subprocess.run([r'C:\Users\manas\AppData\Roaming\npm\webcmd.cmd','--profile','bookbridge-release','--session','v2-circulation-checks-r5','browser','run','--stdin','--no-snapshot-diff','--timeout','40','-f','json'],input=program,text=True,capture_output=True,encoding='utf-8',timeout=50);print(r.stdout);print(r.stderr)

assert r.returncode==0
